      if (length(intersec) > 0) {
        rows_v[[wi]] <- cbind(intersec, v, w)
      }
    }
    rows_v <- rows_v[!vapply(rows_v, is.null, logical(1))]
    if (length(rows_v) > 0) {
      per_vertex[[v]] <- do.call(rbind, rows_v)
      NoTriangles <- NoTriangles + nrow(per_vertex[[v]])
